# 🐛 bug report

Importing an asset without any import specifiers from a different bundle doesn't execute it.

## 🤔 Expected Behavior

Prints "run1".

## 😯 Current Behavior

Prints nothing, run1 is never executed.

```js
(function () {
  function $parcel$bundleWrapper() {
    if ($parcel$bundleWrapper._executed) return;
    $parcel$bundleWrapper._executed = true;
    var $parcel$global = typeof globalThis !== 'undefined' ? globalThis : typeof self !== 'undefined' ? self : typeof window !== 'undefined' ? window : typeof global !== 'undefined' ? global : {};
    var parcelRequire = $parcel$global.parcelRequire427e;
    // -------------- missing parcelRequire() and $id$init() calls
    // ASSET: a.js
    var $d391011066ea13e85c54c18f0c9355bd$exports = {};
    parcelRequire.register("6rdEb", function () {
      return $d391011066ea13e85c54c18f0c9355bd$exports;
    });
  }
  var $parcel$referencedAssets = ["6rdEb"];
  for (var $parcel$i = 0; $parcel$i < $parcel$referencedAssets.length; $parcel$i++) {
    parcelRequire427e.registerBundle($parcel$referencedAssets[$parcel$i], $parcel$bundleWrapper);
  }
})();
```

## 💁 Possible Solution

`parcelRequire` and the init call for that asset should still be inserted in the async child bundles

Seems like `isUnusedValue` is too aggressive here: https://github.com/parcel-bundler/parcel/blob/49ac217507d5914a2e38ca402593d26527cdb673/packages/shared/scope-hoisting/src/link.js#L616 and the bundle import isn't inserted

## 💻 Code Sample

```js
// index.js
if (Date.now() < 0) {
	require("./run1.js");
}
import("./async.js");


// async.js
import "./run1.js";

// run1.js
console.log("run1");
```


